"""Apply the illustrated student route to the retained course source."""
from copy import deepcopy
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def text(title, value, check=None):
    b = dict(kind='text', title=title, text=value)
    if check:
        b['check'] = check
    return b


def code(title, value):
    return dict(kind='code', title=title, code=value)


def image(name, title, notes, crop=None, marks=None, width=None):
    ext = '.png' if name.startswith(('01-', '01b-', '01c-', '01d-', '02-', '42-', '44-', '45-')) else '.jpg'
    focus = json.loads((ROOT/'evidence/walkthrough/focus.json').read_text(encoding='utf-8'))
    key = name
    if name in focus:
        f = focus[name]
        name = f.get('source', name)
        crop = crop or [f['x'], f['y'], f['w'], f['h']]
    b = dict(kind='image', title=title, path=f'evidence/walkthrough/{name}{ext}', notes=notes)
    if crop:
        b['crop'] = crop
    if marks:
        b['marks'] = marks
    if width:
        b['display_mm'] = width
    b['evidence_key'] = key
    return b


def retained_image(path, title, notes, crop=None, width=None):
    b = dict(kind='image', path=path, title=title, notes=notes)
    if crop:
        b['crop'] = crop
    if width:
        b['display_mm'] = width
    return b


