    def normalize(x):
        if isinstance(x,dict):return {k:normalize(v) for k,v in x.items()}
        if isinstance(x,list):return [normalize(v) for v in x]
        if isinstance(x,str):
            x=x.replace(' На этом компьютере использован отдельный учебный экземпляр MariaDB.', '')
            x=x.replace(' В данной работе роль оформления не имеет права удалять заказ.', '')
            x=x.replace('Сначала сохранить файл, затем выполнять его фрагмент в phpMyAdmin.', 'Сначала сохранить файл, затем выполнять его законченный фрагмент в phpMyAdmin. Если блок помечен «продолжение», собрать все его части в одном файле до выполнения. Отдельный обрывок незаконченного CREATE TABLE не выполнять; команда заканчивается точкой с запятой.')
            x=x.replace('Открыть INPUT_MAPPING.md из архива исходных материалов. В нём для каждого XLSX указаны', 'Открыть docs/INPUT_MAPPING.md из своего variant-NN.zip в Блокноте. Та же карта образца находится в project/INPUT_MAPPING.md отдельного demo-data.zip. В ней для каждого XLSX указаны')
            x=x.replace('Затем постройте ER-диаграмму описанным выше способом.', 'Далее перейти к следующим этапам «Проверить структуру, уникальность и ссылки» и «Получить ER-диаграмму и экспортировать PDF».')
            x=x.replace('Открыть Структура и проверьте десять предметных таблиц.', 'Открыть «Структура» и проверить десять предметных таблиц.')
            for a,b in substitutions.items():x=x.replace(a,b)
        return x
